mapper.delete:
DELETE FROM SEARCH_KEYWORD_HISTORY
WHERE MEMBER_NO = #{memberNo}
  AND SEARCH_HISTORY_NO NOT IN (
      SELECT SEARCH_HISTORY_NO
      FROM (
          SELECT SEARCH_HISTORY_NO
          FROM SEARCH_KEYWORD_HISTORY
          WHERE MEMBER_NO = #{memberNo}
          ORDER BY LAST_SEARCHED_AT DESC
      )
      WHERE ROWNUM <= #{keepCount}
  )

DELETE FROM SEARCH_KEYWORD_HISTORY
WHERE MEMBER_NO = #{memberNo}
  AND UPPER(KEYWORD) = UPPER(#{keyword})
